{"status":"candidate","chosen_option":"prefix_remainder_counts","assumptions":["Input follows the specified format and contains at least n integers."],"observations":[{"statement":"The program must count nonempty contiguous subarrays whose sum is divisible by k, including when integers are negative.","source_ids":["task"]},{"statement":"The constraints are 1 ≤ n ≤ 200000 and 1 ≤ k ≤ 1000000000.","source_ids":["task"]},{"statement":"The required output is one integer count.","source_ids":["task"]}],"artifact":{"code":"import sys


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, k = data[0], data[1]

    frequencies = {0: 1}
    prefix = 0
    count = 0
    for value in data[2:2 + n]:
        prefix = (prefix + value) % k
        count += frequencies.get(prefix, 0)
        frequencies[prefix] = frequencies.get(prefix, 0) + 1

    print(count)


if __name__ == "__main__":
    main()
